// PreserveAdaptiveEncoding returns the fresh TypeInfo with its storage encoding pinned to the
// existing TypeInfo's encoding, when both represent the same type family.
//
// A freshly-constructed TypeInfo (for example, one built from a sql.Type during an ALTER TABLE
// statement) picks its storage encoding from the global UseAdaptiveEncoding default. When a column
// was originally persisted under a legacy address encoding (e.g. val.StringAddrEnc), silently
// adopting the adaptive default would corrupt the on-disk representation. This function copies the
// persisted encoding from the existing column's TypeInfo onto the fresh TypeInfo so the storage
// encoding remains stable across schema modifications.
//
// It is a no-op (returns fresh unchanged) when:
//   - existing is nil,
//   - the two TypeInfos belong to different type families (e.g. VARCHAR->TEXT, Point->LineString),
//   - the type family does not use a variable adaptive encoding (e.g. integer types).
//
// It returns nil when fresh is nil.
//
// Covered type families: string/text (blobStringType), binary/blob (varBinaryType), JSON
// (jsonType), and all concrete geometry types (pointType, linestringType, polygonType,
// multipointType, multilinestringType, multipolygonType, geomcollType, geometryType).
func PreserveAdaptiveEncoding(existing TypeInfo, fresh TypeInfo) TypeInfo {
	if existing == nil {
		return fresh
	}
	if fresh == nil {
		return nil
	}

	switch f := fresh.(type) {
	case *blobStringType:
		if e, ok := existing.(*blobStringType); ok {
			return f.WithEncoding(e.Encoding())
		}
	case *varBinaryType:
