// preserveColumnEncodings returns a schema equivalent to |newSch| except that any column also
// present in |oldSch| (matched by name) has its storage encoding pinned to the encoding persisted
// in |oldSch|, when both belong to the same type family. This keeps a table rewrite or schema
// change from migrating existing columns onto the global adaptive-encoding default when they were
// originally persisted under a legacy address encoding. See typeinfo.PreserveAdaptiveEncoding.
func preserveColumnEncodings(oldSch, newSch schema.Schema) (schema.Schema, error) {
	if oldSch == nil {
		return newSch, nil
	}

	oldCols := oldSch.GetAllCols()
	cols := newSch.GetAllCols().GetColumns()
	changed := false
	for i := range cols {
		oldCol, ok := oldCols.GetByNameCaseInsensitive(cols[i].Name)
		if !ok {
			continue
		}
		preserved := typeinfo.PreserveAdaptiveEncoding(oldCol.TypeInfo, cols[i].TypeInfo)
		if preserved != cols[i].TypeInfo {
			cols[i].TypeInfo = preserved
			changed = true
		}
	}
	if !changed {
		return newSch, nil
	}

	newColColl := schema.NewColCollection(cols...)
	return schema.NewSchema(newColColl, newSch.GetPkOrdinals(), newSch.GetCollation(), newSch.Indexes(), newSch.Checks())
